  `group_rule_num_size` int(11) NOT NULL DEFAULT 1 COMMENT '杀猪组子单数量，1为没有子单',
  `group_rule_num_num` int(11) NOT NULL DEFAULT 1 COMMENT '杀猪组小订单第几单',
  `clear_group` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `oid`(`oid`) USING BTREE,
  INDEX `uid`(`uid`) USING BTREE,
  INDEX `endtime`(`endtime`) USING BTREE,
  INDEX `addtime`(`addtime`) USING BTREE,
  INDEX `c_status`(`c_status`) USING BTREE,
  INDEX `parent_uid`(`parent_uid`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `group_id`(`group_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8849 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员-订单表' ROW_FORMAT = Dynamic;

