-- ----------------------------
-- Table structure for xy_group
-- ----------------------------
DROP TABLE IF EXISTS `xy_group`;
CREATE TABLE `xy_group`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称',
  `money` decimal(18, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '最低金额',
  `bili` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '比例',
  `order_num` int(11) NULL DEFAULT 0 COMMENT '订单数量',
  `is_roll` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否允许重复做单',
  `agent_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '管理员编号',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 42 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

