-- ----------------------------
-- Table structure for xy_group_rule
-- ----------------------------
DROP TABLE IF EXISTS `xy_group_rule`;
CREATE TABLE `xy_group_rule`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `group_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '分组编号',
  `order_num` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '第几单',
  `user_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户编号',
  `commission_type` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '0=百分比  1=固定值',
  `commission_value` decimal(15, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '佣金',
  `tips_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '弹窗ID',
  `add_orders` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '增加做单数',
  `order_type` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '0=默认模式 1=叠加模式',
  `order_price` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '做单价格比例，多个用|隔开',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '弹窗图片',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 234 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分组做单信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of xy_group_rule
-- ----------------------------

