-- ----------------------------
-- Table structure for xy_inyectar
-- ----------------------------
DROP TABLE IF EXISTS `xy_inyectar`;
CREATE TABLE `xy_inyectar`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `uid` int(10) UNSIGNED NOT NULL COMMENT '用户',
  `date` date NOT NULL COMMENT '打针日期',
  `order_num` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '预计打针订单序号 0=下一个',
  `scale` decimal(10, 1) UNSIGNED NOT NULL DEFAULT 1.0 COMMENT '打针倍率',
  `in_oid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '打针订单号',
  `in_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '打针实际时间',
  `in_amount` decimal(8, 2) NULL DEFAULT 0.00 COMMENT '打针订单金额',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `uid_2`(`uid`) USING BTREE,
  INDEX `uid`(`uid`, `date`, `order_num`, `in_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

