-- Records of xy_msg
-- ----------------------------

-- ----------------------------
-- Table structure for xy_notice
-- ----------------------------
DROP TABLE IF EXISTS `xy_notice`;
CREATE TABLE `xy_notice`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tel` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '信息标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '正文内容',
  `addtime` int(11) NOT NULL COMMENT '发表时间',
  `is_read` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否已读 1未读 2已读',
  `read_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '阅读时间',
  `need_confirm` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否需要确认',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `addtime`(`addtime`) USING BTREE,
  INDEX `is_read`(`is_read`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员-消息表' ROW_FORMAT = Dynamic;

