-- Records of xy_notice
-- ----------------------------

-- ----------------------------
-- Table structure for xy_pay
-- ----------------------------
DROP TABLE IF EXISTS `xy_pay`;
CREATE TABLE `xy_pay`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sort` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序',
  `name` varchar(128) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT '展示名称',
  `name2` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT '代码',
  `type` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型',
  `ico` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '图标',
  `min` double(18, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '最小金额',
  `max` double(18, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '最大金额',
  `pay_commission` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '佣金',
  `ewm` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '二维码',
  `status` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否启用0禁用 1启用',
  `is_payout` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为出款渠道',
  `url` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '付款链接',
  `username` varchar(100) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '用户名',
  `usercode` varchar(200) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '用户代码',
  `mch_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '商户号',
  `secret` varchar(100) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '密钥',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `name2`(`name2`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 86 CHARACTER SET = utf8 COLLATE = utf8_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of xy_pay
-- ----------------------------

