  `uid` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '会员ID',
  `addtime` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '读取时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `mid-uid`(`mid`, `uid`) USING BTREE,
  INDEX `mid`(`mid`) USING BTREE,
  INDEX `uid`(`uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员-消息读取记录表' ROW_FORMAT = Dynamic;

